semantic::Geometry projectCache(const std::filesystem::path& root,const epubviews::ViewSet& view,const semantic::Geometry& geometry,const QByteArray& binding){if(!geometry)return geometry;auto path=file(root,view);if(!std::filesystem::exists(path))return geometry;auto cache=semantic::readChecked(path,Cap);identity(view,cache);auto page=geometry->data;need(page["document"]==view.receipt["document"]&&page["page"].toInt(-1)>=0&&page["page"].toInt()<view.receipt["pages"].toInt(),"epub-cache-page-binding");QJsonArray rows;for(const auto* kind:{"highlights","notes"})for(auto v:cache[kind].toArray()){auto entry=v.toObject();auto original=entry["originalAnchor"].toObject();need(semantic::validAnchorSegments(original),"epub-cache-original-segments");need(library::validId(entry["id"].toString())&&entry["originalAnchorDigest"].toString().toLatin1()==underlay::digest(QJsonDocument(original).toJson(QJsonDocument::Compact)).toHex()&&original["document"]==view.receipt["document"]&&original["revision"]==view.receipt["source_sha"],"epub-cache-original-binding");QJsonObject row{{"id",entry["id"]},{"kind",kind},{"originalAnchorDigest",entry["originalAnchorDigest"]},{"status",entry["status"]},{"reason",entry["reason"]}};if(entry["status"]=="resolved"){need(entry["page"].isDouble()&&entry["page"].toDouble()==entry["page"].toInt(-1)&&entry["page"].toInt()>=0&&entry["page"].toInt()<view.receipt["pages"].toInt()&&entry["layoutId"]==view.receipt["layout_id"]&&entry["viewId"]==view.id,"epub-cache-target-binding");row["targetPage"]=entry["page"];auto all=entry["fragments"].toArray();need(entry["fragments"].isArray()&&all.size()<=1000,"epub-cache-fragment-capacity");if(all.isEmpty())need(entry["kind"]=="spine-start"&&original["scope"]=="page-location"&&entry["page"]==0,"epub-cache-empty-fragments");else need(all.first().toObject()["page"]==entry["page"],"epub-cache-first-target");int previous=-1,previousEnd=-1;QJsonArray fragments;for(auto fv:all){auto f=fv.toObject();need(f["page"].isDouble()&&f["page"].toDouble()==f["page"].toInt(-1)&&f["page"].toInt()>=0&&f["page"].toInt()<view.receipt["pages"].toInt(),"epub-cache-fragment-page");need(f["page"].toInt()>previous||(original.contains("segments")&&f["page"].toInt()==previous&&f["first"].toInt(-1)>=previousEnd),"epub-cache-fragment-order");previous=f["page"].toInt();previousEnd=f["last"].toInt(-1);if(f["page"]==page["page"])fragments.append(f);}row["fragments"]=fragments;}else need(entry["status"]=="unresolved","epub-cache-status");rows.append(row);}page["annotationResolutions"]=rows;page["annotationLayoutId"]=view.receipt["layout_id"];return semantic::decodeGeometry(page,binding);}
